// Fake DB: rows come back in index/arbitrary order, and id 5 is MISSING.
function dbFetch(ids) {
  const table = { 7: 'Ada', 9: 'Bob', 3: 'Cy', 2: 'Dot' };
  // Return only existing rows, in a DB-chosen order (NOT key order):
  return [9, 3, 7, 2].filter(id => ids.includes(id)).map(id => ({ id, name: table[id] }));
}

const keys = [7, 9, 5, 3, 2]; // note: 5 has no row
const rows = dbFetch(keys);

// BUGGY: returns DB-order rows verbatim — length and order both wrong.
const buggy = rows.map(r => r.name);

// FIXED: build a Map by id, then walk keys in input order.
const byId = new Map(rows.map(r => [r.id, r]));
const aligned = keys.map(k => (byId.has(k) ? byId.get(k).name : null));

console.log('keys:    ' + JSON.stringify(keys));
console.log('buggy:   ' + JSON.stringify(buggy));
console.log('aligned: ' + JSON.stringify(aligned));

