function batchAuthors(ids, rows) {
  // FIX ME: currently returns rows verbatim (wrong order, wrong length,
  // and throws if a row is missing). Make it honor the contract.
  const byId = new Map(rows.map(r => [r.id, r]));
  return ids.map(id => byId.has(id) ? byId.get(id) : null);
}

// --- harness ---
const rows = [{ id: 9, name: 'Bob' }, { id: 3, name: 'Cy' }, { id: 7, name: 'Ada' }];
const keys = [7, 9, 5, 3];
const out = batchAuthors(keys, rows);
if (out.length !== keys.length) throw new Error('length mismatch');
if (out[0] && out[0].name === 'Ada' && out[1] && out[1].name === 'Bob' && out[2] === null && out[3] && out[3].name === 'Cy') {
  console.log('CONTRACT OK');
} else {
  console.log('CONTRACT VIOLATED');
}
